{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Subnet is not configured with a Network Security Group",
      "resource": "azurerm_subnet.data_subnet",
      "severity": "HIGH",
      "explanation": "The subnet is not associated with a Network Security Group, potentially exposing resources within the subnet to unauthorized access."
    }
  ],
  "patched_code": "resource \"azurerm_network_security_group\" \"data_nsg\" {
  name                = \"healthcare-patient-portal-with-hipaa-compliance-nsg-data\"
  location            = azurerm_resource_group.healthcare_portal.location
  resource_group_name = azurerm_resource_group.healthcare_portal.name

  # Example rule, adjust according to your needs
  security_rule {
    name                       = \"allow-inbound-ssh\"
    priority                   = 100
    direction                  = \"Inbound\"
    access                     = \"Allow\"
    protocol                   = \"Tcp\"
    source_port_range          = \"*\"
    destination_port_range     = \"22\"
    source_address_prefix      = \"*\"
    destination_address_prefix = \"*\"
  }
}

resource \"azurerm_subnet_network_security_group_association\" \"data_nsg_association\" {
  subnet_id                 = azurerm_subnet.data_subnet.id
  network_security_group_id = azurerm_network_security_group.data_nsg.id
}

resource \"azurerm_subnet\" \"data_subnet\" {
  name                 = \"healthcare-patient-portal-with-hipaa-compliance-subnet-data\"
  resource_group_name  = azurerm_resource_group.healthcare_portal.name
  virtual_network_name = azurerm_virtual_network.healthcare_vnet.name
  address_prefixes     = [\"10.0.3.0/24\"]
}",
  "fix_summary": "Added a Network Security Group and associated it with the subnet to improve security posture."
}
